let ctx, drops, fontSize = 14;
self.onmessage = function(e) {
    var d = e.data;
    if (d.type === 'init') {
        ctx = d.canvas.getContext('2d');
        doResize(d.w, d.h);
        startDraw();
    } else if (d.type === 'resize') {
        if (ctx) doResize(d.w, d.h);
    }
};
function doResize(w, h) {
    ctx.canvas.width = w;
    ctx.canvas.height = h;
    var cols = Math.floor(w / fontSize);
    drops = [];
    for (var i = 0; i < cols; i++) drops[i] = Math.random() * -40;
}
function startDraw() {
    var chars = '01αβγδεζηθικλμνξοπρστυφχψωΑΒΓΔΕΖΗΘΙΚΛΜΝΞΟΠΡΣΤΥΦΧΨΩ';
    setInterval(function() {
        ctx.fillStyle = 'rgba(19,20,23,0.05)';
        ctx.fillRect(0, 0, ctx.canvas.width, ctx.canvas.height);
        ctx.fillStyle = '${ke.rain}';
        ctx.font = fontSize + 'px monospace';
        for (var i = 0; i < drops.length; i++) {
            var c = chars[Math.floor(Math.random() * chars.length)];
            ctx.fillText(c, i * fontSize, drops[i] * fontSize);
            if (drops[i] * fontSize > ctx.canvas.height && Math.random() > 0.975) drops[i] = 0;
            drops[i]++;
        }
    }, 100);
}
